            opacity: 0;
            animation: scan-glow 6s ease-in-out infinite;
        }

        /* Sweeping shine overlay (above content, mostly transparent) */
        a.glow-buttoon::after {
            content: "";
            position: absolute;
            inset: 0;
            border-radius: inherit;
            pointer-events: none;
            background: linear-gradient(135deg, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0) 40%, rgba(171, 230, 161, 0.5) 50%, rgba(0, 0, 0, 0) 60%, rgba(0, 0, 0, 0) 100%);
