            transition: border-bottom-left-radius var(--navbar-radius-speed) var(--navbar-radius-ease) var(--mega-height-speed), border-bottom-right-radius var(--navbar-radius-speed) var(--navbar-radius-ease) var(--mega-height-speed), translate var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
        }

